import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer
from src.events import Recorder

def setup():
    c = sqlite3.connect(":memory:")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c

def state(c):
    return (balance(c, "a"), balance(c, "b"), c.execute("SELECT count(*) FROM ledger").fetchone()[0])

c = setup(); p = Recorder()
for args in [("a","a",1),("a","x",1),("x","a",1),("a","b",0),("a","b",-1),("a","b",True),("a","b",1.0),("a","b",101)]:
    try: transfer(c, p, *args); raise SystemExit("no error %r" % (args,))
    except ValueError: pass
assert state(c) == (100, 20, 0) and p.events == [] and not c.in_transaction

transfer(c, p, "a", "b", 100)
assert state(c) == (0, 120, 1) and len(p.events) == 1

class Boom:
    def publish(self, e): raise RuntimeError
c = setup()
try: transfer(c, Boom(), "a", "b", 5); raise SystemExit("no error")
except RuntimeError: pass
c.rollback(); assert state(c) == (95, 25, 1)

class Wrap:  # fails on ledger insert
    def __init__(self, c): self.c = c
    def execute(self, sql, *a):
        if sql.startswith("INSERT INTO ledger"): raise sqlite3.OperationalError("x")
        return self.c.execute(sql, *a)
    def commit(self): self.c.commit()
    def rollback(self): self.c.rollback()
c = setup(); p = Recorder()
try: transfer(Wrap(c), p, "a", "b", 5); raise SystemExit("no error")
except sqlite3.OperationalError: pass
assert state(c) == (100, 20, 0) and p.events == []

class CommitFail(Wrap):
    def execute(self, sql, *a): return self.c.execute(sql, *a)
    def commit(self): raise sqlite3.OperationalError("commit")
c = setup(); p = Recorder()
try: transfer(CommitFail(c), p, "a", "b", 5); raise SystemExit("no error")
except sqlite3.OperationalError: pass
assert state(c) == (100, 20, 0) and p.events == []
print("ok")
EOF
